# The Finalsite family (edjobs::fetch_finalsite_postings(), edjobs 0.20.0, 2026-11-14;
# claude-notes/2026-11-14_finalsite-family/): each registry row, with its own Job_Link, City and
# k12_list_rules.csv rule, against the district's captured page(s). Expected titles are the routine's output,
# checked against each district's old parser (every difference listed in the README).
# Test titles name the parser and the district so the auto-fix issue finds that district's fixtures.
# Generated by claude-notes/2026-11-14_finalsite-family/make_family_test.R.

finalsite_parse <- function(district, fixture) {
  reg <- read.csv(here::here("k12_district_registry.csv"), stringsAsFactors = FALSE)
  row <- reg[reg$District == district, ]
  expect_equal(nrow(row), 1)
  expect_equal(row$Platform, "Finalsite")
  rules <- read_k12_list_rules(here::here("k12_list_rules.csv"))
  html <- paste(readLines(fixture, warn = FALSE, encoding = "UTF-8"), collapse = "\n")
  r <- parse_finalsite_postings(html, row$Job_Link, row$City, k12_list_rule(rules, district, "List_Start"),
                                  k12_list_rule(rules, district, "List_Stop"), k12_list_rule(rules, district, "Skip_Section"))
  expect_true(all(r$Location == row$City))
  r
}

test_that("parse_finalsite_postings: Custer Public Schools", {
  r <- finalsite_parse("Custer Public Schools", test_path("fixtures", "custer_employment.html"))
  expect_equal(r$Title, c("Superintendent with Principal Duties",
      "PE Teaching Position",
      "Vo-Ag Teaching Position",
      "Music Teaching Position",
      "Route Bus Drivers (CDL or Non CDL)",
      "Activity Bus Drivers (CDL or Non CDL)"))
})

